/* Build 462 — Bundle Deal + Net Profit analyser */
(function(){'use strict';
const money=v=>'$'+Math.round(Number(v)||0).toLocaleString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const rows=[];
function addRow(data={}){rows.push({name:data.name||'',resale:Number(data.resale)||0,qty:Math.max(1,Number(data.qty)||1)});render();}
function removeRow(i){rows.splice(i,1);render();}
function render(){const host=document.getElementById('bundleProfitPanel');if(!host)return;host.innerHTML='<div class="card"><h2>🧺 Bundle Deal Analyser</h2><div class="muted">Add the items in a seller\'s bundle, then enter one asking price.</div><div id="bundleRows">'+(rows.length?rows.map((r,i)=>`<div class="bundle-row"><input class="input br-name" data-i="${i}" value="${esc(r.name)}" placeholder="Item / game"><input class="input br-resale" data-i="${i}" type="number" min="0" step="1" value="${r.resale||''}" placeholder="Resale"><input class="input br-qty" data-i="${i}" type="number" min="1" step="1" value="${r.qty}"><button class="btn danger br-remove" data-i="${i}">✕</button></div>`).join(''):'<div class="empty">No bundle items yet.</div>')+'</div><div class="toolbar"><button class="btn" id="bundleAdd">＋ Add Item</button><button class="btn primary" id="bundleScan">📷 Add From Scanner</button></div><div class="bundle-inputs"><label>Seller asking price<input id="bundleAsk" class="input" type="number" min="0" step="1" placeholder="0"></label><label>Marketplace fee %<input id="bundleFee" class="input" type="number" min="0" step="0.1" value="0"></label><label>Postage / shipping<input id="bundlePost" class="input" type="number" min="0" step="0.01" value="0"></label><label>Packaging / other costs<input id="bundleOther" class="input" type="number" min="0" step="0.01" value="0"></label></div><div id="bundleResult" class="result"></div></div>';
host.querySelectorAll('.br-name').forEach(e=>e.oninput=()=>{rows[e.dataset.i].name=e.value});host.querySelectorAll('.br-resale').forEach(e=>e.oninput=()=>{rows[e.dataset.i].resale=Number(e.value)||0;calculate()});host.querySelectorAll('.br-qty').forEach(e=>e.oninput=()=>{rows[e.dataset.i].qty=Math.max(1,Number(e.value)||1);calculate()});host.querySelectorAll('.br-remove').forEach(e=>e.onclick=()=>removeRow(Number(e.dataset.i)));host.querySelector('#bundleAdd').onclick=()=>addRow();host.querySelector('#bundleScan').onclick=()=>show('scanner');['bundleAsk','bundleFee','bundlePost','bundleOther'].forEach(id=>host.querySelector('#'+id).addEventListener('input',calculate));calculate();}
function calculate(){const host=document.getElementById('bundleResult');if(!host)return;const resale=rows.reduce((s,r)=>s+r.resale*r.qty,0),ask=Number(document.getElementById('bundleAsk')?.value)||0,feePct=Number(document.getElementById('bundleFee')?.value)||0,post=Number(document.getElementById('bundlePost')?.value)||0,other=Number(document.getElementById('bundleOther')?.value)||0,fee=resale*feePct/100,net=resale-ask-fee-post-other,p25=resale*.25,p30=resale*.30,p40=resale*.40,pct=resale?ask/resale*100:0;let status='ENTER ASKING PRICE',cls='';if(ask){if(ask<=p25){status='🔥 EXCELLENT BUY';cls='success'}else if(ask<=p30){status='✅ GOOD BUY';cls='success'}else if(ask<=p40){status='⚠️ CAUTION';cls=''}else{status='❌ PASS';cls='danger'}}host.innerHTML=`<div class="buygrid"><div class="buy"><span>TOTAL RESALE</span><strong>${money(resale)}</strong></div><div class="buy recommended"><span>25% TARGET</span><strong>${money(p25)}</strong></div><div class="buy"><span>30% TARGET</span><strong>${money(p30)}</strong></div><div class="buy"><span>40% MAXIMUM</span><strong>${money(p40)}</strong></div></div><div class="list-item"><span>Seller asking</span><b>${money(ask)}</b></div><div class="list-item"><span>Buy percentage</span><b>${pct.toFixed(0)}%</b></div><div class="list-item"><span>Marketplace fee</span><b>${money(fee)}</b></div><div class="list-item"><span>Postage + other</span><b>${money(post+other)}</b></div><div class="list-item"><span>Estimated net profit</span><b>${money(net)}</b></div><div class="toolbar"><button class="btn ${cls}" disabled>${status}</button></div>`;}
window.addBundleItemFromScan=function(p){addRow({name:p.title,resale:Number(p.resale)||0,qty:1});document.getElementById('bundleProfitPanel')?.scrollIntoView({behavior:'smooth'});};
function init(){const scanner=document.getElementById('scanner');if(!scanner||document.getElementById('bundleProfitPanel'))return;const section=document.createElement('section');section.id='bundleProfitPanel';section.className='section';section.innerHTML='';scanner.parentNode.insertBefore(section,document.getElementById('pricing'));render();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();setTimeout(init,500);
})();
